# Independent implementation from WHO computation formulas and official XLSX LMS.
# Does not call anthro/anthroplus for its numerical output. Strict lengths; no extrapolation.
lms_centile<-function(z,L,M,S){same_lengths(z,L,M,S);ans<-rep(NA_real_,length(z));ok<-is.finite(z)&is.finite(L)&is.finite(M)&is.finite(S)&M>0&S>0;i<-ok&L==0;ans[i]<-M[i]*exp(S[i]*z[i]);i<-ok&L!=0&(1+L*S*z)>0;ans[i]<-M[i]*(1+L[i]*S[i]*z[i])^(1/L[i]);ans}
lms_adjusted<-function(bmi,L,M,S){same_lengths(bmi,L,M,S);z<-rep(NA_real_,length(bmi));ok<-is.finite(bmi)&bmi>0&is.finite(L)&is.finite(M)&M>0&is.finite(S)&S>0;i<-ok&L==0;z[i]<-log(bmi[i]/M[i])/S[i];i<-ok&L!=0;z[i]<-expm1(L[i]*log(bmi[i]/M[i]))/(L[i]*S[i]);c3<-lms_centile(rep(3,length(z)),L,M,S);c2<-lms_centile(rep(2,length(z)),L,M,S);cn3<-lms_centile(rep(-3,length(z)),L,M,S);cn2<-lms_centile(rep(-2,length(z)),L,M,S);i<-which(ok&z>3);z[i]<-3+(bmi[i]-c3[i])/(c3[i]-c2[i]);i<-which(ok&z< -3);z[i]<- -3+(bmi[i]-cn3[i])/(cn2[i]-cn3[i]);z}
who_z_independent<-function(bmi,sex,age_months,reference){same_lengths(bmi,sex,age_months);n<-length(bmi);pars<-matrix(NA_real_,n,3,dimnames=list(NULL,c('L','M','S')));for(sx in 1:2){i<-which(sex==sx&is.finite(age_months)&age_months>=61&age_months<=228);tab<-reference[reference$sex==sx,];if(length(i))for(nm in c('L','M','S'))pars[i,nm]<-stats::approx(tab$Month,tab[[nm]],xout=age_months[i],rule=1,ties='ordered')$y};lms_adjusted(bmi,pars[,'L'],pars[,'M'],pars[,'S'])}
category_z<-function(z){out<-rep(NA_character_,length(z));ok<-is.finite(z);out[ok&z< -2]<-'Underweight';out[ok&z>= -2&z<=1]<-'Healthy';out[ok&z>1&z<=2]<-'Overweight';out[ok&z>2]<-'Obesity';out}
# R translation of INEC T7.do lines 53-112; sequential tie priority 12,13,23 (last matching pair wins).
# Raw input values are never modified; discarded third readings exist only in local temporary copies.
inec_pair_mean<-function(x1,x2,x3){same_lengths(x1,x2,x3);third<-x3;d12<-abs(x1-x2);third[which(is.finite(d12)&d12<=0.5)]<-NA_real_;d13<-abs(x1-third);d23<-abs(x2-third);dm<-pmin(d12,d13,d23,na.rm=TRUE);dm[!is.finite(dm)]<-NA_real_;v<-rep(NA_real_,length(x1));pair<-rep(NA_character_,length(x1));i<-which(!is.na(d12)&d12==dm);v[i]<-(x1[i]+x2[i])/2;pair[i]<-'12';i<-which(!is.na(d13)&d13==dm);v[i]<-(x1[i]+third[i])/2;pair[i]<-'13';i<-which(!is.na(d23)&d23==dm);v[i]<-(x2[i]+third[i])/2;pair[i]<-'23';required_missing<-is.finite(d12)&d12>0.5&!is.finite(x3);data.frame(value=v,pair=pair,third_ignored=is.finite(x3)&is.finite(d12)&d12<=0.5,required_third_missing=required_missing,tie_count=rowSums(cbind(d12==dm,d13==dm,d23==dm),na.rm=TRUE))}
